import React, { useEffect } from "react";
import { graphql, type HeadFC, type PageProps } from "gatsby";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Layout from "../components/Layout";
import SEO from "../components/seo";
import I18nHeadProvider from "../components/I18nHeadProvider";
import ContactForm from "../components/contactForm";
import data from "../data/data.json";
import type { Company } from "../interfaces";
import images from "../images";

const info: Company = data[0];

const ContractorsPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();

  useEffect(() => {
    document.body.style.backgroundImage = `url(${images.bg.src})`;
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundRepeat = "no-repeat";

    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundRepeat = "";
    };
  }, []);

  const contentBlocks = t("contractors.blocks", {
    returnObjects: true,
  }) as Array<{
    kicker?: string;
    title: string;
    description?: string;
    textLine1?: string;
    textLine2?: string;
    bullets?: Array<{ item: string }>;
  }>;

  const scrollToForm = () => {
    const el = document.getElementById("contractors-form");
    if (!el) return;
    el.scrollIntoView({ behavior: "smooth", block: "start" });
  };

  return (
    <Layout data={info}>
      <section className="pt-10 pb-6 sm:pt-14 sm:pb-10">
        <div className={styles.container}>
          <div className="text-center">
            <p className="uppercase tracking-[0.2em] text-xs text-verde">
              {t("contractors.hero.kicker")}
            </p>
            <h1 className="text-3xl sm:text-5xl poppins-bold text-light mx-auto max-w-5xl mt-3">
              {t("contractors.hero.title")}
            </h1>
            <p className="mt-4 text-lg sm:text-xl text-light/85 mx-auto max-w-4xl">
              {t("contractors.hero.subtitle")}
            </p>

            <div className="mx-auto mt-8 flex flex-col sm:flex-row items-center justify-center gap-3">
              <button
                type="button"
                onClick={scrollToForm}
                className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
              >
                {t("contractors.hero.primaryCta")}
              </button>
              <a
                href={info.whatsapp}
                target="_blank"
                rel="noreferrer"
                className="rounded-full bg-purplesemilight px-5 py-2.5 text-light text-center"
              >
                {t("contractors.hero.secondaryCta")}
              </a>
            </div>
          </div>
        </div>
      </section>

      <section className="py-10 sm:py-14">
        <div className={styles.container}>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {contentBlocks.map((block, idx) => (
              <article key={block.title} className={styles.card}>
                {block.kicker ? (
                  <p className="uppercase tracking-[0.2em] text-xs text-verde">
                    {block.kicker}
                  </p>
                ) : null}
                <h2 className="text-xl font-semibold text-light">{block.title}</h2>
                {block.description ? (
                  <p className="mt-3 text-light/75 leading-relaxed">
                    {block.description}
                  </p>
                ) : null}
                {block.textLine1 || block.textLine2 ? (
                  <p className="mt-3 text-light/85 leading-relaxed">
                    {block.textLine1}
                    {block.textLine1 && block.textLine2 ? <br /> : null}
                    {block.textLine2}
                  </p>
                ) : null}
                {Array.isArray(block.bullets) && block.bullets.length > 0 ? (
                  <ul className="mt-4 list-disc pl-6 space-y-2 text-light/80">
                    {block.bullets.map((bullet, bIdx) => (
                      <li key={`${idx}-${bullet.item}-${bIdx}`}>{bullet.item}</li>
                    ))}
                  </ul>
                ) : null}
              </article>
            ))}
          </div>
        </div>
      </section>

      <section id="contractors-form" className="py-10 sm:py-14 scroll-mt-28">
        <div className={styles.container}>
          <article className={styles.card}>
            <h2 className="text-2xl sm:text-3xl poppins-regular text-verde text-center">
              {t("contractors.form.title")}
            </h2>
            <p className="mt-4 text-light/80 text-center max-w-3xl mx-auto">
              {t("contractors.form.subtitle")}
            </p>
            <div className="mt-8 flex justify-center">
              <a
                href={info.whatsapp}
                target="_blank"
                rel="noreferrer"
                className="rounded-full bg-secondary px-5 py-2.5 text-light text-center"
              >
                {t("contractors.form.cta")}
              </a>
            </div>
            <div className="mt-8 flex justify-center">
              <ContactForm />
            </div>
          </article>
        </div>
      </section>
    </Layout>
  );
};

export const Head: HeadFC = ({ data, pageContext }) => (
  <I18nHeadProvider data={data} pageContext={pageContext}>
    <SEO
      data={info}
      titleKey="contractors.metaTitle"
      descriptionKey="contractors.metaDescription"
      pathname="/contractors/"
      schemaType="ProfessionalService"
    />
  </I18nHeadProvider>
);

export default ContractorsPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  container: "w-full max-w-5xl mx-auto px-4 sm:px-0",
  card: "rounded-3xl border border-white/15 bg-white/5 p-6",
};
